{"tool":"sandbox","code":"use std::fs;
use std::time::Instant;

const N_FULL: u64 = 300_000_000;
const MULT: u32 = 2_654_435_761;
const OUT_DIR: &str = "/work/artifacts";
const OUT_PATH: &str = "/work/artifacts/result.json";

macro_rules! ensure {
    ($cond:expr, $($arg:tt)*) => {
        if !($cond) {
            return Err(format!($($arg)*));
        }
    };
}

#[inline(always)]
fn h(i: u64) -> u32 {
    (i as u32).wrapping_mul(MULT)
}

struct Stats {
    n: u64,
    distinct_a: u64,
    distinct_b: u64,
    min: u32,
    max: u32,
    lower: u32,
    upper: u32,
    inverse: u32,
}

fn lap(t: &mut Instant, label: &str) {
    eprintln!("  [{:>8.3} s] {}", t.elapsed().as_secs_f64(), label);
    *t = Instant::now();
}

// (bucket, exclusive prefix count) of the bucket holding 0-based rank
fn locate(hist: &[u64], rank: u64) -> Option<(usize, u64)> {
    let mut acc = 0u64;
    for (b, &c) in hist.iter().enumerate() {
        if rank < acc + c {
            return Some((b, acc));
        }
        acc += c;
    }
    None
}

fn solve(n: u64) -> Result<Stats, String> {
    ensure!(n >= 2 && n % 2 == 0, "n must be even and >= 2, got {}", n);
    ensure!(n <= (1u64 << 32), "n = {} exceeds 2^32", n);
    eprintln!("solve(n={})", n);
    let mut t = Instant::now();

    // Pass 1: min, max, histogram of the top 16 bits.
    let mut hist = vec![0u64; 65536];
    let mut mn = u32::MAX;
    let mut mx = 0u32;
    for i in 0..n {
        let v = h(i);
        if v < mn {
            mn = v;
        }
        if v > mx {
            mx = v;
        }
        hist[(v >> 16) as usize] += 1;
    }
    let total: u64 = hist.iter().sum();
    ensure!(total == n, "sum(hist) = {} != n = {}", total, n);
    lap(&mut t, "pass 1: min/max/hist");

    // Median = mean of 0-based ranks n/2-1 and n/2.
    let r_lo = n / 2 - 1;
    let r_hi = n / 2;
    let (b_lo, cum_lo) = locate(&hist, r_lo).ok_or_else(|| format!("rank {} not located", r_lo))?;
    let (b_hi, cum_hi) = locate(&hist, r_hi).ok_or_else(|| format!("rank {} not located", r_hi))?;
    eprintln!("  lower rank {} in bucket {}, upper rank {} in bucket {}", r_lo, b_lo, r_hi, b_hi);

    // Pass 2: collect only the bucket(s) holding the two median ranks.
    let mut lo_vals: Vec<u32> = Vec::with_capacity(hist[b_lo] as usize);
    let mut hi_vals: Vec<u32> = Vec::with_capacity(if b_hi != b_lo { hist[b_hi] as usize } else { 0 });
    for i in 0..n {
        let v = h(i);
        let b = (v >> 16) as usize;
        if b == b_lo {
            lo_vals.push(v);
        } else if b == b_hi {
            hi_vals.push(v);
        }
    }
    ensure!(lo_vals.len() as u64 == hist[b_lo], "bucket {} collected {} != hist {}", b_lo, lo_vals.len(), hist[b_lo]);
    if b_hi != b_lo {
        ensure!(hi_vals.len() as u64 == hist[b_hi], "bucket {} collected {} != hist {}", b_hi, hi_vals.len(), hist[b_hi]);
    }
    lap(&mut t, "pass 2: collect median bucket(s)");
    lo_vals.sort_unstable();
    let lower = lo_vals[(r_lo - cum_lo) as usize];
    let upper = if b_hi == b_lo {
        lo_vals[(r_hi - cum_lo) as usize]
    } else {
        hi_vals.sort_unstable();
        hi_vals[(r_hi - cum_hi) as usize]
    };
    ensure!(lower <= upper, "lower {} > upper {}", lower, upper);
    ensure!(mn <= lower && upper <= mx, "order violated: min {} lower {} upper {} max {}", mn, lower, upper, mx);

    // Method A: modular inverse of the odd multiplier (Newton), then bijection check.
    let a = MULT;
    let mut inv = a; // odd a satisfies a*a == 1 (mod 8): 3 correct bits to start
    for _ in 0..5 {
        inv = inv.wrapping_mul(2u32.wrapping_sub(a.wrapping_mul(inv)));
    }
    ensure!(a.wrapping_mul(inv) == 1, "a*inv = {} != 1", a.wrapping_mul(inv));
    let mut bad = 0u64;
    for i in 0..n {
        if inv.wrapping_mul(h(i)) != (i as u32) {
            bad += 1;
        }
    }
    ensure!(bad == 0, "{} indices violated inv*h(i) == i", bad);
    // inv is a left inverse of h on [0,n), so h is injective there: distinct = n.
    let distinct_a = n;
    lap(&mut t, "method A: inverse + bijection check");

    // Method B: 2^28-bit bitmap (32 MiB), 16 passes split by top 4 bits.
    let mut bm = vec![0u64; 1usize << 22];
    let mut distinct_b = 0u64;
    for p in 0u32..16 {
        bm.fill(0);
        let mut hits = 0u64;
        let mut newly = 0u64;
        for i in 0..n {
            let v = h(i);
            if (v >> 28) == p {
                hits += 1;
                let idx = (v & 0x0FFF_FFFF) as usize;
                let w = idx >> 6;
                let bit = 1u64 << (idx & 63);
                if (bm[w] & bit) == 0 {
                    bm[w] |= bit;
                    newly += 1;
                }
            }
        }
        ensure!(newly == hits, "bitmap pass {}: newly set {} != hits {}", p, newly, hits);
        distinct_b += newly;
        eprintln!("  bitmap pass {:>2}: hits {} newly set {}", p, hits, newly);
    }
    drop(bm);
    ensure!(distinct_b == distinct_a, "distinct mismatch: A {} vs B {}", distinct_a, distinct_b);
    lap(&mut t, "method B: bitmap 16 passes");

    Ok(Stats { n, distinct_a, distinct_b, min: mn, max: mx, lower, upper, inverse: inv })
}

// Brute-force reference: collect everything, sort, dedup.
fn brute(n: u64) -> (u64, u32, u32, u32, u32) {
    let mut v: Vec<u32> = (0..n).map(h).collect();
    v.sort_unstable();
    let mn = v[0];
    let mx = v[v.len() - 1];
    let lo = v[(n / 2 - 1) as usize];
    let hi = v[(n / 2) as usize];
    v.dedup();
    (v.len() as u64, mn, mx, lo, hi)
}

fn selftest() -> Result<(), String> {
    for n in [10u64, 1_000_000u64] {
        let s = solve(n)?;
        let (d, mn, mx, lo, hi) = brute(n);
        ensure!(s.distinct_a == d, "selftest n={}: distinct_a {} != brute {}", n, s.distinct_a, d);
        ensure!(s.distinct_b == d, "selftest n={}: distinct_b {} != brute {}", n, s.distinct_b, d);
        ensure!(s.min == mn, "selftest n={}: min {} != brute {}", n, s.min, mn);
        ensure!(s.max == mx, "selftest n={}: max {} != brute {}", n, s.max, mx);
        ensure!(s.lower == lo, "selftest n={}: lower {} != brute {}", n, s.lower, lo);
        ensure!(s.upper == hi, "selftest n={}: upper {} != brute {}", n, s.upper, hi);
        eprintln!("selftest n={} PASS: distinct={} min={} max={} lower={} upper={}", n, d, mn, mx, lo, hi);
    }
    Ok(())
}

fn json_escape(s: &str) -> String {
    let q = char::from(34u8);
    let bs = char::from(92u8);
    let mut o = String::new();
    for c in s.chars() {
        if c == q || c == bs {
            o.push(bs);
            o.push(c);
        } else if (c as u32) < 32 {
            o.push_str(&format!("{}u{:04x}", bs, c as u32));
        } else {
            o.push(c);
        }
    }
    o
}

fn run() -> Result<String, String> {
    let t0 = Instant::now();
    fs::create_dir_all(OUT_DIR).map_err(|e| format!("create_dir_all {}: {}", OUT_DIR, e))?;
    eprintln!("== self-test: solve vs brute force ==");
    selftest()?;
    eprintln!("== full run: n={} ==", N_FULL);
    let s = solve(N_FULL)?;
    ensure!(s.n == N_FULL, "n mismatch: {}", s.n);
    let avg = ((s.lower as u64) + (s.upper as u64)) as f64 / 2.0;
    let json = format!(
        r#"{{"n":{},"distinct":{},"distinct_method_a_bijection":{},"distinct_method_b_bitmap":{},"min":{},"max":{},"median_lower":{},"median_upper":{},"median_average":{:.1},"inverse":{},"selftest_passed":true,"note":"bounded-memory streaming equivalent of full Vec sort"}}"#,
        s.n, s.distinct_a, s.distinct_a, s.distinct_b, s.min, s.max, s.lower, s.upper, avg, s.inverse
    );
    eprintln!("total elapsed {:.3} s", t0.elapsed().as_secs_f64());
    Ok(json)
}

fn main() {
    match run() {
        Ok(json) => {
            if let Err(e) = fs::write(OUT_PATH, json.as_bytes()) {
                eprintln!("FAILED to write {}: {}", OUT_PATH, e);
                std::process::exit(1);
            }
            eprintln!("wrote {}", OUT_PATH);
            println!("{}", json);
        }
        Err(msg) => {
            eprintln!("FAILED: {}", msg);
            let body = format!(r#"{{"n":{},"error":"{}"}}"#, N_FULL, json_escape(&msg));
            let _ = fs::create_dir_all(OUT_DIR);
            if let Err(e) = fs::write(OUT_PATH, body.as_bytes()) {
                eprintln!("FAILED to write error file: {}", e);
            }
            println!("{}", body);
            std::process::exit(1);
        }
    }
}
","summary":"Bounded-memory streaming solve: self-test against brute force for n=10 and n=1,000,000 (distinct, min, max, lower, upper), then full N=300,000,000 with bijection (inverse) distinct count cross-checked by a 16-pass 2^28-bit bitmap; writes /work/artifacts/result.json and reports per-phase timings."}

{"tool":"sandbox","code":"use std::fs;
use std::thread;
use std::time::Instant;

const N_FULL: u64 = 300_000_000;
const MULT: u32 = 2_654_435_761;
const OUT_DIR: &str = "/work/artifacts";
const OUT_PATH: &str = "/work/artifacts/result.json";
const BM_WORDS: usize = 1usize << 22;
const BM_MASK: usize = BM_WORDS - 1;
const PASSES: u32 = 16;
const MAX_THREADS: usize = 4;

macro_rules! ensure {
    ($cond:expr, $($arg:tt)*) => {
        if !($cond) {
            return Err(format!($($arg)*));
        }
    };
}

#[inline(always)]
fn h(i: u64) -> u32 {
    (i as u32).wrapping_mul(MULT)
}

struct Stats {
    n: u64,
    distinct_a: u64,
    distinct_b: u64,
    min: u32,
    max: u32,
    lower: u32,
    upper: u32,
    inverse: u32,
}

fn lap(t: &mut Instant, label: &str) {
    eprintln!("  [{:>9.3} s] {}", t.elapsed().as_secs_f64(), label);
    *t = Instant::now();
}

fn locate(hist: &[u64], rank: u64) -> Option<(usize, u64)> {
    let mut acc = 0u64;
    for (b, &c) in hist.iter().enumerate() {
        if rank < acc + c {
            return Some((b, acc));
        }
        acc += c;
    }
    None
}

fn modinv_pow2_32(a: u32) -> u32 {
    let mut x = a;
    for _ in 0..5 {
        x = x.wrapping_mul(2u32.wrapping_sub(a.wrapping_mul(x)));
    }
    x
}

fn pass1_and_bijection(n: u64, inv: u32) -> (u32, u32, Vec<u64>, u64) {
    let mut hist = vec![0u64; 65536];
    let mut mn = u32::MAX;
    let mut mx = 0u32;
    let mut bad = 0u64;
    for i in 0..n {
        let v = h(i);
        mn = mn.min(v);
        mx = mx.max(v);
        hist[(v >> 16) as usize] += 1;
        bad += (inv.wrapping_mul(v) != (i as u32)) as u64;
    }
    (mn, mx, hist, bad)
}

fn pass2_collect(n: u64, b_lo: usize, b_hi: usize) -> (Vec<u32>, Vec<u32>) {
    let mut lo_vals: Vec<u32> = Vec::new();
    let mut hi_vals: Vec<u32> = Vec::new();
    for i in 0..n {
        let v = h(i);
        let b = (v >> 16) as usize;
        if b == b_lo {
            lo_vals.push(v);
        } else if b == b_hi {
            hi_vals.push(v);
        }
    }
    (lo_vals, hi_vals)
}

fn bitmap_pass(n: u64, p: u32, bm: &mut [u64]) -> (u64, u64) {
    let mut hits = 0u64;
    let mut newly = 0u64;
    for i in 0..n {
        let v = h(i);
        if (v >> 28) == p {
            hits += 1;
            let idx = (v & 0x0FFF_FFFF) as usize;
            let w = (idx >> 6) & BM_MASK;
            let bit = 1u64 << (idx & 63);
            let old = bm[w];
            newly += ((old & bit) == 0) as u64;
            bm[w] = old | bit;
        }
    }
    (hits, newly)
}

fn worker_threads() -> usize {
    thread::available_parallelism()
        .map(|x| x.get())
        .unwrap_or(1)
        .clamp(1, MAX_THREADS)
}

fn bitmap_all_passes(n: u64, threads: usize) -> Result<Vec<(u32, u64, u64)>, String> {
    let mut all: Vec<(u32, u64, u64)> = Vec::new();
    let mut panicked = false;
    thread::scope(|s| {
        let handles: Vec<_> = (0..threads)
            .map(|t| {
                s.spawn(move || {
                    let mut bm = vec![0u64; BM_WORDS];
                    let mut out: Vec<(u32, u64, u64)> = Vec::new();
                    let mut p = t as u32;
                    while p < PASSES {
                        bm.fill(0);
                        let (hits, newly) = bitmap_pass(n, p, &mut bm);
                        eprintln!("  bitmap pass {:>2}: hits {} newly set {}", p, hits, newly);
                        out.push((p, hits, newly));
                        p += threads as u32;
                    }
                    out
                })
            })
            .collect();
        for hd in handles {
            match hd.join() {
                Ok(v) => all.extend(v),
                Err(_) => panicked = true,
            }
        }
    });
    ensure!(!panicked, "a bitmap worker thread panicked");
    all.sort_by_key(|x| x.0);
    ensure!(all.len() == PASSES as usize, "bitmap produced {} passes", all.len());
    for (k, x) in all.iter().enumerate() {
        ensure!(x.0 == k as u32, "bitmap pass {} missing", k);
    }
    Ok(all)
}

fn solve(n: u64) -> Result<Stats, String> {
    ensure!(n >= 2 && n % 2 == 0, "n must be even and >= 2, got {}", n);
    ensure!(n <= (1u64 << 32), "n = {} exceeds 2^32", n);
    eprintln!("solve(n={})", n);
    let mut t = Instant::now();

    let inv = modinv_pow2_32(MULT);
    ensure!(MULT.wrapping_mul(inv) == 1, "MULT*inv = {} != 1", MULT.wrapping_mul(inv));

    let (mn, mx, hist, bad) = pass1_and_bijection(n, inv);
    let total: u64 = hist.iter().sum();
    ensure!(total == n, "sum(hist) = {} != n = {}", total, n);
    ensure!(bad == 0, "{} indices violated inv*h(i) == i", bad);
    lap(&mut t, "pass 1 (min/max/hist) + method A bijection check");

    let r_lo = n / 2 - 1;
    let r_hi = n / 2;
    let (b_lo, cum_lo) = locate(&hist, r_lo).ok_or_else(|| format!("rank {} not located", r_lo))?;
    let (b_hi, cum_hi) = locate(&hist, r_hi).ok_or_else(|| format!("rank {} not located", r_hi))?;
    eprintln!("  lower rank {} in bucket {}, upper rank {} in bucket {}", r_lo, b_lo, r_hi, b_hi);

    let (mut lo_vals, hi_vals) = pass2_collect(n, b_lo, b_hi);
    ensure!(lo_vals.len() as u64 == hist[b_lo], "bucket {} collected {} != hist {}", b_lo, lo_vals.len(), hist[b_lo]);
    if b_hi != b_lo {
        ensure!(hi_vals.len() as u64 == hist[b_hi], "bucket {} collected {} != hist {}", b_hi, hi_vals.len(), hist[b_hi]);
    }
    lap(&mut t, "pass 2: collect median bucket(s)");

    lo_vals.sort_unstable();
    let (lower, upper) = if b_hi == b_lo {
        (lo_vals[(r_lo - cum_lo) as usize], lo_vals[(r_hi - cum_lo) as usize])
    } else {
        let mut hv = hi_vals;
        hv.sort_unstable();
        (lo_vals[(r_lo - cum_lo) as usize], hv[(r_hi - cum_hi) as usize])
    };
    ensure!(lower <= upper, "lower {} > upper {}", lower, upper);
    ensure!(mn <= lower && upper <= mx, "order violated: min {} lower {} upper {} max {}", mn, lower, upper, mx);
    lap(&mut t, "median selection + order check");

    let threads = worker_threads();
    eprintln!("  bitmap worker threads: {}", threads);
    let passes = bitmap_all_passes(n, threads)?;
    let mut distinct_b = 0u64;
    let mut hits_total = 0u64;
    for &(p, hits, newly) in passes.iter() {
        ensure!(newly == hits, "bitmap pass {}: newly set {} != hits {}", p, newly, hits);
        let lo_b = (p as usize) * 4096;
        let expect: u64 = hist[lo_b..lo_b + 4096].iter().sum();
        ensure!(hits == expect, "bitmap pass {}: hits {} != hist count {}", p, hits, expect);
        distinct_b += newly;
        hits_total += hits;
    }
    ensure!(hits_total == n, "bitmap hits {} != n {}", hits_total, n);
    let distinct_a = n;
    ensure!(distinct_b == distinct_a, "distinct mismatch: A {} vs B {}", distinct_a, distinct_b);
    lap(&mut t, "method B: bitmap 16 passes");

    Ok(Stats { n, distinct_a, distinct_b, min: mn, max: mx, lower, upper, inverse: inv })
}

fn brute(n: u64) -> (u64, u32, u32, u32, u32) {
    let mut v: Vec<u32> = (0..n).map(h).collect();
    v.sort_unstable();
    let mn = v[0];
    let mx = v[v.len() - 1];
    let lo = v[(n / 2 - 1) as usize];
    let hi = v[(n / 2) as usize];
    v.dedup();
    (v.len() as u64, mn, mx, lo, hi)
}

fn selftest() -> Result<(), String> {
    for n in [10u64, 1_000_000u64] {
        let s = solve(n)?;
        let (d, mn, mx, lo, hi) = brute(n);
        ensure!(s.distinct_a == d, "selftest n={}: distinct_a {} != brute {}", n, s.distinct_a, d);
        ensure!(s.distinct_b == d, "selftest n={}: distinct_b {} != brute {}", n, s.distinct_b, d);
        ensure!(s.min == mn, "selftest n={}: min {} != brute {}", n, s.min, mn);
        ensure!(s.max == mx, "selftest n={}: max {} != brute {}", n, s.max, mx);
        ensure!(s.lower == lo, "selftest n={}: lower {} != brute {}", n, s.lower, lo);
        ensure!(s.upper == hi, "selftest n={}: upper {} != brute {}", n, s.upper, hi);
        eprintln!("selftest n={} PASS: distinct={} min={} max={} lower={} upper={}", n, d, mn, mx, lo, hi);
    }
    Ok(())
}

fn json_escape(s: &str) -> String {
    let q = char::from(34u8);
    let bs = char::from(92u8);
    let mut o = String::new();
    for c in s.chars() {
        if c == q || c == bs {
            o.push(bs);
            o.push(c);
        } else if (c as u32) < 32 {
            o.push_str(&format!("{}u{:04x}", bs, c as u32));
        } else {
            o.push(c);
        }
    }
    o
}

fn result_json(s: &Stats) -> String {
    let q = char::from(34u8).to_string();
    let avg = ((s.lower as u64) + (s.upper as u64)) as f64 / 2.0;
    let tpl = format!(
        "{{@n@:{},@distinct@:{},@distinct_method_a_bijection@:{},@distinct_method_b_bitmap@:{},@min@:{},@max@:{},@median_lower@:{},@median_upper@:{},@median_average@:{:.1},@inverse@:{},@selftest_passed@:true,@note@:@bounded-memory streaming equivalent of full Vec sort@}}",
        s.n, s.distinct_a, s.distinct_a, s.distinct_b, s.min, s.max, s.lower, s.upper, avg, s.inverse
    );
    tpl.replace('@', &q)
}

fn error_json(msg: &str) -> String {
    let q = char::from(34u8).to_string();
    let head = format!("{{@n@:{},@error@:@", N_FULL).replace('@', &q);
    format!("{}{}{}}}", head, json_escape(msg), q)
}

fn run() -> Result<String, String> {
    let t0 = Instant::now();
    fs::create_dir_all(OUT_DIR).map_err(|e| format!("create_dir_all {}: {}", OUT_DIR, e))?;
    eprintln!("== self-test: solve vs brute force ==");
    selftest()?;
    eprintln!("== full run: n={} ==", N_FULL);
    let s = solve(N_FULL)?;
    ensure!(s.n == N_FULL, "n mismatch: {}", s.n);
    ensure!(s.distinct_a == s.distinct_b, "final distinct mismatch");
    let json = result_json(&s);
    eprintln!("total elapsed {:.3} s", t0.elapsed().as_secs_f64());
    Ok(json)
}

fn main() {
    match run() {
        Ok(json) => {
            if let Err(e) = fs::write(OUT_PATH, json.as_bytes()) {
                eprintln!("FAILED to write {}: {}", OUT_PATH, e);
                std::process::exit(1);
            }
