    let mut x = a;
    for _ in 0..5 {
        x = x.wrapping_mul(2u32.wrapping_sub(a.wrapping_mul(x)));
    }
    x
}

fn locate(hist: &[u64], rank: u64) -> Option<(usize, u64)> {
    let mut acc = 0u64;
    for (b, &c) in hist.iter().enumerate() {
        if rank < acc + c {
            return Some((b, acc));
        }
        acc += c;
    }
    None
}

// Scan 1: min, max, top-16-bit histogram, and inv*h(i) == i for every i (method A).
fn scan1(n: u64, inv: u64) -> (u64, u64, Vec<u64>, u64) {
    let mut hist = vec![0u64; 65536];
    let mut mn = u64::MAX;
    let mut mx = 0u64;
    let mut bad = 0u64;
    let mut i = 0u64;
    let mut v = 0u64; // invariant: v == h(i)
    while i < n {
        if v < mn {
            mn = v;
        }
        if v > mx {
            mx = v;
        }
        hist[(v >> 16) as usize] += 1;
        bad += (((inv * v) & MASK32) != i) as u64;
        v = (v + M) & MASK32;
        i += 1;
    }
    (mn, mx, hist, bad)
}

// One bitmap pass (method B): mark values with top 4 bits == p, count newly set bits,
// and collect the median bucket(s) in the same scan.
fn bitmap_pass(
    n: u64,
    p: u64,
    bm: &mut [u64],
    b_lo: usize,
    b_hi: usize,
    lo: &mut Vec<u64>,
    hi: &mut Vec<u64>,
) -> (u64, u64) {
    let mut i = 0u64;
    let mut v = 0u64; // invariant: v == h(i)
    let mut hits = 0u64;
    let mut newly = 0u64;
    while i < n {
        if (v >> 28) == p {
            hits += 1;
            let idx = (v & 0x0FFF_FFFF) as usize;
            let w = idx >> 6;
            let bit = 1u64 << (idx & 63);
            let old = bm[w];
            newly += ((old & bit) == 0) as u64;
            bm[w] = old | bit;
            let b = (v >> 16) as usize;
            if b == b_lo {
                lo.push(v);
            } else if b == b_hi {
                hi.push(v);
            }
        }
        v = (v + M) & MASK32;
        i += 1;
    }
    (hits, newly)
}

fn solve(n: u64, verbose: bool) -> Result<Stats, String> {
    ensure!(n >= 2 && n % 2 == 0 && n <= (1u64 << 32), "n must be even with 2 <= n <= 2^32, got {}", n);
    let mut t = Instant::now();

    // Method A: Newton inverse, verified; bijection check runs inside scan 1.
    let a = M as u32;
    let inv32 = modinv(a);
    ensure!(a.wrapping_mul(inv32) == 1, "a*inv = {} != 1", a.wrapping_mul(inv32));
    let inv = inv32 as u64;

    let (mn, mx, hist, bad) = scan1(n, inv);
    let total: u64 = hist.iter().sum();
    ensure!(total == n, "sum(hist) = {} != n = {}", total, n);
    ensure!(bad == 0, "{} indices violated inv*h(i) == i", bad);
    ensure!(mn <= mx, "min {} > max {}", mn, mx);
    if verbose {
        lap(&mut t, "scan 1: min/max/hist + bijection check (method A)");
    }

    // 0-based median ranks and the buckets that contain them.
    let r_lo = n / 2 - 1;
    let r_hi = n / 2;
    let (b_lo, cum_lo) = locate(&hist, r_lo).ok_or_else(|| format!("rank {} not located", r_lo))?;
    let (b_hi, cum_hi) = locate(&hist, r_hi).ok_or_else(|| format!("rank {} not located", r_hi))?;
    let same = b_lo == b_hi;
    if verbose {
        eprintln!("  median ranks {} / {} in buckets {} / {}", r_lo, r_hi, b_lo, b_hi);
    }

    // Method B: 16 bitmap passes over 2^28 bits (32 MiB), median buckets collected in-pass.
    let mut lo: Vec<u64> = Vec::with_capacity(hist[b_lo] as usize);
    let mut hi: Vec<u64> = Vec::new();
    if !same {
        hi.reserve(hist[b_hi] as usize);
    }
    let mut bm = vec![0u64; BM_WORDS];
    let mut distinct_b = 0u64;
    let mut hits_total = 0u64;
    for p in 0..PASSES {
        bm.fill(0);
        let (hits, newly) = bitmap_pass(n, p, &mut bm, b_lo, b_hi, &mut lo, &mut hi);
        ensure!(newly == hits, "pass {}: newly set {} != hits {}", p, newly, hits);
        let first = p as usize * BUCKETS_PER_PASS;
        let expect: u64 = hist[first..first + BUCKETS_PER_PASS].iter().sum();
        ensure!(hits == expect, "pass {}: hits {} != histogram count {}", p, hits, expect);
        distinct_b += newly;
        hits_total += hits;
        if verbose {
            lap(&mut t, &format!("bitmap pass {:>2}: hits {} distinct {}", p, hits, newly));
        }
    }
    drop(bm);
    ensure!(hits_total == n, "hits {} != n {}", hits_total, n);
    ensure!(distinct_b == n, "distinct mismatch: A {} vs B {}", n, distinct_b);

    // Median selection from the collected bucket(s).
    ensure!(lo.len() as u64 == hist[b_lo], "bucket {} collected {} != hist {}", b_lo, lo.len(), hist[b_lo]);
    lo.sort_unstable();
    let (lower, upper) = if same {
        (lo[(r_lo - cum_lo) as usize], lo[(r_hi - cum_lo) as usize])
    } else {
        ensure!(hi.len() as u64 == hist[b_hi], "bucket {} collected {} != hist {}", b_hi, hi.len(), hist[b_hi]);
        hi.sort_unstable();
        (lo[(r_lo - cum_lo) as usize], hi[(r_hi - cum_hi) as usize])
    };
    ensure!(lower <= upper, "lower {} > upper {}", lower, upper);
    ensure!(mn <= lower && upper <= mx, "order violated: min {} lower {} upper {} max {}", mn, lower, upper, mx);
    if verbose {
        lap(&mut t, "median select + order checks");
    }

    Ok(Stats { n, distinct_a: n, distinct_b, min: mn, max: mx, lower, upper, inverse: inv })
}

// Brute-force reference: collect, sort, dedup.
fn brute(n: u64) -> (u64, u64, u64, u64, u64) {
    let mut v: Vec<u64> = (0..n).map(h).collect();
    v.sort_unstable();
    let mn = v[0];
    let mx = v[v.len() - 1];
    let lo = v[(n / 2 - 1) as usize];
    let hi = v[(n / 2) as usize];
    v.dedup();
    (v.len() as u64, mn, mx, lo, hi)
}

fn selftest() -> Result<(), String> {
    for n in [10u64, 1_000_000u64] {
        let s = solve(n, false)?;
        let (d, mn, mx, lo, hi) = brute(n);
        ensure!(s.distinct_a == d && s.distinct_b == d, "selftest n={}: distinct A {} B {} brute {}", n, s.distinct_a, s.distinct_b, d);
        ensure!(s.min == mn && s.max == mx, "selftest n={}: min/max {}/{} vs brute {}/{}", n, s.min, s.max, mn, mx);
        ensure!(s.lower == lo && s.upper == hi, "selftest n={}: median {}/{} vs brute {}/{}", n, s.lower, s.upper, lo, hi);
        eprintln!("selftest n={} PASS distinct={} min={} max={} lower={} upper={}", n, d, mn, mx, lo, hi);
    }
    Ok(())
}

fn json_escape(s: &str) -> String {
    let q = char::from(34u8);
    let bs = char::from(92u8);
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        if c == q || c == bs {
            o.push(bs);
            o.push(c);
        } else if (c as u32) < 32 {
            o.push(' ');
        } else {
            o.push(c);
        }
    }
    o
}

fn result_json(s: &Stats) -> String {
    let avg = (s.lower + s.upper) as f64 / 2.0;
    format!(
        r#"{{"n":{},"distinct":{},"distinct_method_a_bijection":{},"distinct_method_b_bitmap":{},"min":{},"max":{},"median_lower":{},"median_upper":{},"median_average":{:.1},"inverse":{},"selftest_passed":true,"note":"bounded-memory streaming equivalent of full Vec sort"}}"#,
        s.n, s.distinct_a, s.distinct_a, s.distinct_b, s.min, s.max, s.lower, s.upper, avg, s.inverse
    )
}

fn error_json(msg: &str) -> String {
    format!(r#"{{"n":{},"error":"{}"}}"#, N_FULL, json_escape(msg))
}

fn run() -> Result<String, String> {
    let t0 = Instant::now();
    fs::create_dir_all(OUT_DIR).map_err(|e| format!("create_dir_all {}: {}", OUT_DIR, e))?;
    eprintln!("== self-test: solve vs brute force ==");
    selftest()?;
    eprintln!("== full run n={} ==", N_FULL);
    let s = solve(N_FULL, true)?;
    ensure!(s.n == N_FULL, "n mismatch {}", s.n);
    eprintln!("total elapsed {:.3} s", t0.elapsed().as_secs_f64());
    Ok(result_json(&s))
}

fn main() {
    match run() {
        Ok(json) => {
            if let Err(e) = fs::write(OUT_PATH, json.as_bytes()) {
                eprintln!("FAILED to write {}: {}", OUT_PATH, e);
                std::process::exit(1);
            }
            eprintln!("wrote {}", OUT_PATH);
            println!("{}", json);
        }
        Err(msg) => {
            eprintln!("FAILED: {}", msg);
            let body = error_json(&msg);
            let _ = fs::create_dir_all(OUT_DIR);
            let _ = fs::write(OUT_PATH, body.as_bytes());
            println!("{}", body);
            std::process::exit(1);
        }
    }
}
